alter table public.studio_media add column placement text not null default 'gallery' check (placement in ('cover','gallery')), add column sort_order integer not null default 0 check(sort_order between 0 and 100000); create unique index studio_media_one_cover on public.studio_media(slot) where published and placement='cover'; drop index public.studio_media_published_slot; create index studio_media_gallery_order on public.studio_media(slot,placement,sort_order,id) where published;
